use super::*;
use self::core::wire::Capability;
use std::{sync::Arc,collections::BTreeMap};
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn fixture(name:&str)->Vec<u8>{fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b1/fixtures").join(format!("{name}.json"))).unwrap()}
struct Qa{root:PathBuf,repo:Repository,time:Arc<Mutex<String>>}
impl Qa{
 fn new()->Self{let root=std::env::temp_dir().join("opencode").join(format!("5d3b4b-{}",id()));let time=Arc::new(Mutex::new("2026-10-28T12:00:00Z".into()));let mut repo=Repository::new(root.clone(),Policy::qa());repo.clock=Clock{fixed:Some(time.clone())};Self{root,repo,time}}
 fn ready()->Self{let q=Self::new();*q.time.lock().unwrap()="2026-10-26T12:00:00Z".into();q.repo.initialize_new().unwrap();q.repo.accept_trust_episode(&id(),0,&[fixture("trust1")]).unwrap();q}
 fn install(&self,name:&str)->String{let g=self.repo.open_existing().unwrap().generation;self.repo.record_verified_installation(&id(),g,&fixture(name),&[Capability::Direct,Capability::Inverse]).unwrap().installation_id.unwrap()}
 fn sql(&self)->Connection{schema::open(&self.repo.db(),false).unwrap()}
 fn admit(&self,i:&str)->String{let p=self.repo.prepare_activation(ActivationIntent::Admit,Some(i),None,None).unwrap();let aid=p.admission_id.clone().unwrap();self.repo.confirm_activation(&id(),&p).unwrap();aid}
 fn select(&self,i:&str,a:&str)->ActivationPreview{let p=self.repo.prepare_activation(ActivationIntent::Select,Some(i),Some(a),None).unwrap();self.repo.confirm_activation(&id(),&p).unwrap();p}
 fn legacy()->Self{let mut q=Self::new();q.repo.policy=Policy::import_qa();let source=Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4b/legacy");fs::create_dir(&q.root).unwrap();fs::create_dir(q.root.join("fiscal")).unwrap();for p in ["fiscal-initialization.json","fiscal-initialized.json","fiscal/repository.sqlite3"]{fs::copy(source.join(p),q.root.join(p)).unwrap();}q}
}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn code<T>(r:Result<T>,expected:&str){match r{Err(e)=>assert_eq!(e.code,expected),Ok(_)=>panic!("Expected {expected}")}}
fn literal(c:&Connection)->Vec<(String,Vec<u8>,Vec<u8>)>{let mut s=c.prepare("SELECT id,body,receipt FROM operations ORDER BY seq").unwrap();s.query_map([],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap().collect::<rusqlite::Result<Vec<_>>>().unwrap()}

#[test]fn native_legacy_database_migrates_to_two_with_literal_operations_and_blobs(){let q=Qa::legacy();let before=schema::preserved(&q.sql()).unwrap();let rows=literal(&q.sql());assert_eq!(schema::version(&q.sql()).unwrap(),1);let status=q.repo.open_existing().unwrap();assert_eq!(status.generation,5);assert_eq!(schema::version(&q.sql()).unwrap(),2);assert_eq!(literal(&q.sql()),rows);assert_eq!(schema::preserved(&q.sql()).unwrap(),before);let originals:serde_json::Value=serde_json::from_slice(&fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4b/legacy/originals.json")).unwrap()).unwrap();for object in originals["objects"].as_array().unwrap(){let b=bytes(&q.sql(),object["table"].as_str().unwrap(),object["hash"].as_str().unwrap(),limits::OBJECT_BYTES).unwrap();assert_eq!(core::hashes::sha256(&b),object["sha256"]);}let copy=fs::read_dir(q.root.join("fiscal/recovery/migration-2")).unwrap().next().unwrap().unwrap().path();let c=schema::open(&copy.join("repository.sqlite3"),true).unwrap();assert_eq!(schema::version(&c).unwrap(),1);assert_eq!(literal(&c),rows);assert_eq!(q.repo.open_existing().unwrap().generation,5);}
#[test]fn new_schema_two_reopens_with_no_effective_admission_or_selection(){let q=Qa::ready();assert_eq!(schema::version(&q.sql()).unwrap(),2);assert_eq!(count(&q.sql(),"effective_admissions").unwrap(),0);assert_eq!(q.repo.selection_status().unwrap().selection,SelectionIdentity::integrated());assert_eq!(q.repo.open_existing().unwrap().generation,1);}
#[test]fn installation_admission_and_selection_are_distinct_operations(){let q=Qa::ready();let i=q.install("package1");assert_eq!(count(&q.sql(),"effective_admissions").unwrap(),0);assert_eq!(q.repo.selection_status().unwrap().selection.kind,"embedded");let a=q.admit(&i);assert_eq!(count(&q.sql(),"effective_admissions").unwrap(),1);assert_eq!(q.repo.selection_status().unwrap().selection.generation,0);q.select(&i,&a);let selected=q.repo.selection_status().unwrap();assert_eq!(selected.selection.generation,1);assert!(selected.eligibility.unwrap().eligible);assert!(selected.execution.contains("remain closed"));assert_eq!(q.repo.open_existing().unwrap().generation,4);assert_eq!(q.sql().query_row("SELECT state FROM admissions",[],|r|r.get::<_,String>(0)).unwrap(),"recorded-not-executable");}
#[test]fn selected_a_remains_current_after_install_b_b_requires_explicit_selection(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);let p=q.select(&a,&aa);let before=q.repo.selection_status().unwrap().selection;let b=q.install("package2");let current=q.repo.selection_status().unwrap();assert_eq!(current.selection,before);assert!(current.eligibility.unwrap().eligible);assert_eq!(q.sql().query_row("SELECT revision FROM accepted_heads",[],|r|r.get::<_,u64>(0)).unwrap(),2);let ba=q.admit(&b);q.select(&b,&ba);assert_ne!(q.repo.selection_status().unwrap().selection.id,p.selection_id);code(q.repo.prepare_activation(ActivationIntent::Select,Some(&a),Some(&aa),None),"REVISION_ROLLBACK");assert_eq!(count(&q.sql(),"rollback_uses").unwrap(),0);}
#[test]fn deactivation_is_explicit_and_does_not_allow_old_selection_reactivation(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);q.install("package2");let p=q.repo.prepare_activation(ActivationIntent::Deactivate,None,None,None).unwrap();q.repo.confirm_activation(&id(),&p).unwrap();let current=q.repo.selection_status().unwrap();assert_eq!(current.selection.kind,"embedded");assert_eq!(current.selection.generation,2);code(q.repo.prepare_activation(ActivationIntent::Select,Some(&a),Some(&aa),None),"REVISION_ROLLBACK");assert_eq!(q.sql().query_row("SELECT revision FROM accepted_heads",[],|r|r.get::<_,u64>(0)).unwrap(),2);}
#[test]fn revocation_blocks_selected_a_without_rewriting_selection(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);let before=q.repo.selection_status().unwrap().selection;let g=q.repo.open_existing().unwrap().generation;q.repo.accept_trust_episode(&id(),g,&[fixture("revoked")]).unwrap();let current=q.repo.selection_status().unwrap();assert_eq!(current.selection,before);let e=current.eligibility.unwrap();assert!(!e.eligible);assert_eq!(e.reason.as_deref(),Some("KEY_REVOKED"));assert_eq!(e.operations.len(),0);}
#[test]fn signed_floor_and_epoch_changes_are_not_bypassed_by_continuity(){for trust in ["floor2","epoch2"]{let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);q.install("package2");let g=q.repo.open_existing().unwrap().generation;q.repo.accept_trust_episode(&id(),g,&[fixture(trust)]).unwrap();assert!(!q.repo.selection_status().unwrap().eligibility.unwrap().eligible);assert_eq!(q.repo.selection_status().unwrap().selection.installation_id.as_deref(),Some(a.as_str()));}}
#[test]fn withdrawn_selection_is_not_usable_and_original_remains(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);let h=core::hashes::sha256(&fixture("package1"));let g=q.repo.open_existing().unwrap().generation;q.repo.accept_trust_episode(&id(),g,&[fixture("withdrawn")]).unwrap();assert!(!q.repo.selection_status().unwrap().eligibility.unwrap().eligible);assert_eq!(q.repo.read_original(&h).unwrap(),fixture("package1"));}
#[test]fn expired_trust_blocks_selection_use_but_explicit_deactivation_works(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);*q.time.lock().unwrap()="2027-01-02T00:00:00Z".into();assert!(!q.repo.selection_status().unwrap().eligibility.unwrap().eligible);let p=q.repo.prepare_activation(ActivationIntent::Deactivate,None,None,None).unwrap();q.repo.confirm_activation(&id(),&p).unwrap();assert_eq!(q.repo.selection_status().unwrap().selection.kind,"embedded");}
#[test]fn clock_rollback_blocks_deactivation_and_current_eligibility(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);*q.time.lock().unwrap()="2026-10-25T00:00:00Z".into();assert_eq!(q.repo.selection_status().unwrap().eligibility.unwrap().reason.as_deref(),Some("CLOCK_ROLLBACK"));code(q.repo.prepare_activation(ActivationIntent::Deactivate,None,None,None),"CLOCK_ROLLBACK");}
#[test]fn effective_admission_binds_container_and_cannot_be_used_for_other_installation(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);let b=q.install("package2");assert!(!q.repo.activation_eligibility(&b,Some(&aa)).unwrap().eligible);assert!(q.repo.prepare_activation(ActivationIntent::Select,Some(&b),Some(&aa),None).is_err());}
#[test]fn identical_confirmation_returns_same_receipt_conflicting_intention_rejects(){let q=Qa::ready();let a=q.install("package1");let p=q.repo.prepare_activation(ActivationIntent::Admit,Some(&a),None,None).unwrap();let op=id();let x=q.repo.confirm_activation(&op,&p).unwrap();assert_eq!(q.repo.confirm_activation(&op,&p).unwrap(),x);assert_eq!(q.repo.operation_status(&op).unwrap(),Some(x));let aa=p.admission_id.unwrap();let other=q.repo.prepare_activation(ActivationIntent::Select,Some(&a),Some(&aa),None).unwrap();code(q.repo.confirm_activation(&op,&other),"OPERATION_CONFLICT");assert_eq!(count(&q.sql(),"effective_admissions").unwrap(),1);}
#[test]fn changed_repository_generation_requires_new_preview(){let q=Qa::ready();let a=q.install("package1");let p=q.repo.prepare_activation(ActivationIntent::Admit,Some(&a),None,None).unwrap();q.install("package2");code(q.repo.confirm_activation(&id(),&p),"STALE_GENERATION");assert_eq!(count(&q.sql(),"effective_admissions").unwrap(),0);}
#[test]fn selection_cas_is_checked_by_replay_apply_not_frontend_only(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);let mut p=q.repo.prepare_activation(ActivationIntent::Select,Some(&a),Some(&aa),None).unwrap();q.select(&a,&aa);p.repository_generation=q.repo.open_existing().unwrap().generation;code(q.repo.confirm_activation(&id(),&p),"STALE_SELECTION");}
#[test]fn valid_existing_rollback_grant_remains_evidence_only_for_effective_selection(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.install("package2");let packet:serde_json::Value=serde_json::from_slice(&fixture("package1")).unwrap();let target=core::hashes::canonical_hash(&packet["signed"]).unwrap();let g=q.repo.open_existing().unwrap().generation;q.repo.record_rollback_evidence(&id(),g,&fixture("rollback"),&target,2).unwrap();let h=core::hashes::sha256(&fixture("rollback"));code(q.repo.prepare_activation(ActivationIntent::Select,Some(&a),Some(&aa),Some(&h)),"EXCEPTIONAL_SELECTION_BLOCKED");assert_eq!(count(&q.sql(),"rollback_uses").unwrap(),0);assert_eq!(q.sql().query_row("SELECT revision FROM accepted_heads",[],|r|r.get::<_,u64>(0)).unwrap(),2);}
#[test]fn direct_only_trust_does_not_admit_inverse(){let q=Qa::ready();q.repo.accept_trust_episode(&id(),1,&[fixture("trust-direct")]).unwrap();let i=q.repo.record_verified_installation(&id(),2,&fixture("package-direct"),&[Capability::Direct]).unwrap().installation_id.unwrap();let p=q.repo.prepare_activation(ActivationIntent::Admit,Some(&i),None,None).unwrap();assert_eq!(p.eligibility.as_ref().unwrap().operations,[Capability::Direct]);q.repo.confirm_activation(&id(),&p).unwrap();q.select(&i,p.admission_id.as_ref().unwrap());assert_eq!(q.repo.selection_status().unwrap().eligibility.unwrap().operations,[Capability::Direct]);}
#[test]fn activation_does_not_touch_salary_history_or_issue_execution(){let q=Qa::ready();let sentinel=b"QA salary sentinel";fs::write(q.root.join("payroll.sqlite3"),sentinel).unwrap();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);assert_eq!(fs::read(q.root.join("payroll.sqlite3")).unwrap(),sentinel);assert!(q.repo.selection_status().unwrap().execution.contains("remain closed"));}
#[test]fn corrupted_effective_projection_is_not_repaired(){let q=Qa::ready();let a=q.install("package1");let aa=q.admit(&a);q.select(&a,&aa);q.sql().execute("DELETE FROM selection_head",[]).unwrap();code(q.repo.selection_status(),"CORRUPT_PROJECTION");assert_eq!(count(&q.sql(),"selection_head").unwrap(),0);}
#[test]fn new_actions_have_versioned_receipts_and_legacy_receipts_stay_literal(){let q=Qa::ready();let a=q.install("package1");let old=literal(&q.sql());let aa=q.admit(&a);q.select(&a,&aa);let now=literal(&q.sql());assert_eq!(&now[..old.len()],old.as_slice());let r:Receipt=serde_json::from_slice(&now[2].2).unwrap();assert_eq!(r.execution,"effective-admission-v1-not-authorized-for-execution");}
#[test]fn migration_precommit_fault_preserves_source_and_verified_copy_then_retries(){let q=Qa::legacy();let before=literal(&q.sql());tests::FAULT.with(|f|*f.borrow_mut()=Some("migration-before-commit".into()));assert!(q.repo.open_existing().is_err());tests::FAULT.with(|f|*f.borrow_mut()=None);assert_eq!(schema::version(&q.sql()).unwrap(),1);assert_eq!(literal(&q.sql()),before);q.repo.open_existing().unwrap();assert_eq!(schema::version(&q.sql()).unwrap(),2);assert_eq!(literal(&q.sql()),before);}
#[test]fn migration_postcommit_fault_never_claims_rollback(){let q=Qa::legacy();tests::FAULT.with(|f|*f.borrow_mut()=Some("migration-after-commit".into()));code(q.repo.open_existing(),"MIGRATION_COMMITTED_RECOVERY_PENDING");tests::FAULT.with(|f|*f.borrow_mut()=None);assert_eq!(schema::version(&q.sql()).unwrap(),2);assert_eq!(q.repo.open_existing().unwrap().generation,5);}
#[test]fn pending_or_corrupt_migration_copy_blocks_without_replacement(){let q=Qa::legacy();tests::FAULT.with(|f|*f.borrow_mut()=Some("backup-created".into()));assert!(q.repo.open_existing().is_err());tests::FAULT.with(|f|*f.borrow_mut()=None);let before=fs::read(q.repo.db()).unwrap();assert!(q.repo.open_existing().is_err());assert_eq!(fs::read(q.repo.db()).unwrap(),before);assert_eq!(schema::version(&q.sql()).unwrap(),1);}
#[test]fn pending_regular_backup_is_validated_by_legacy_protocol_before_migration(){let q=Qa::legacy();let c=q.sql();let m=paths::marker(&q.root.join("fiscal-initialized.json")).unwrap();c.execute_batch("BEGIN IMMEDIATE").unwrap();let copy=recovery::backup(&q.repo,&c,&m).unwrap();c.execute_batch("ROLLBACK").unwrap();drop(c);let before=fs::read(copy.join("repository.sqlite3")).unwrap();assert_eq!(q.repo.open_existing().unwrap().generation,5);assert_eq!(fs::read(copy.join("repository.sqlite3")).unwrap(),before);assert_eq!(schema::version(&schema::open(&copy.join("repository.sqlite3"),true).unwrap()).unwrap(),1);}

fn child(q:&Qa,mode:&str,stop:&str,op:&str)->std::process::Child{std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","fiscal_repository::activation_tests::process_child","--ignored","--nocapture"]).env("FISCAL4B_ROOT",&q.root).env("FISCAL4B_MODE",mode).env("NOMINA_FISCAL_STOP",stop).env("FISCAL4B_OP",op).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap()}
#[test]fn admission_identity_is_discoverable_after_restart_without_becoming_authority(){let q=Qa::ready();let i=q.install("package1");let a=q.admit(&i);let mut reopened=Repository::new(q.root.clone(),Policy::qa());reopened.clock=q.repo.clock.clone();let e=reopened.activation_eligibility(&i,None).unwrap();assert!(e.admission_refs.iter().any(|r|r.admission_id==a&&r.version==1));assert_eq!(reopened.selection_status().unwrap().selection.generation,0);}
#[test]fn corrupt_retained_migration_evidence_blocks_new_mutations(){let q=Qa::legacy();q.repo.open_existing().unwrap();let copy=fs::read_dir(q.root.join("fiscal/recovery/migration-2")).unwrap().next().unwrap().unwrap().path();fs::write(copy.join("repository.sqlite3"),b"corrupt-copy").unwrap();let before=fs::read(q.repo.db()).unwrap();assert!(q.repo.open_existing().is_err());assert_eq!(fs::read(q.repo.db()).unwrap(),before);assert_eq!(schema::version(&q.sql()).unwrap(),2);}
#[test]fn actual_selection_process_kill_and_retry_is_idempotent(){use std::io::BufRead;let mut records=vec![];for stop in ["operation-before-commit","operation-after-commit"]{let q=Qa::legacy();q.repo.open_existing().unwrap();let(_,items)=q.repo.installation_metadata(10,"").unwrap();let i=&items.iter().max_by_key(|i|i.revision).unwrap().installation_id;let aa=q.admit(i);let p=q.repo.prepare_activation(ActivationIntent::Select,Some(i),Some(&aa),None).unwrap();fs::write(q.root.join("selection-request.json"),core::canonical::bytes(&p.action).unwrap()).unwrap();let op=id();let mut process=child(&q,"select",stop,&op);let mut seen=false;for line in std::io::BufReader::new(process.stdout.take().unwrap()).lines(){if line.unwrap().contains(&format!("FISCAL_READY:{stop}")){seen=true;break;}}assert!(seen);process.kill().unwrap();process.wait().unwrap();let committed=stop=="operation-after-commit";assert_eq!(q.repo.operation_status(&op).unwrap().is_some(),committed);let receipt=q.repo.confirm_activation(&op,&p).unwrap();assert_eq!(receipt.generation,7);assert_eq!(q.repo.selection_status().unwrap().selection.generation,1);records.push(serde_json::json!({"point":stop,"externallyTerminated":true,"committedAfterKill":committed,"afterRetryGeneration":7,"selectionEvents":1}));}fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4b/selection-crashes.json"),serde_json::to_vec_pretty(&records).unwrap()).unwrap();}
#[test]fn actual_process_migration_kills_before_after_commit_preserve_five_legacy_receipts(){use std::io::BufRead;let mut records=vec![];for stop in ["migration-backup-ready","migration-after-ddl","migration-before-commit","migration-after-commit","migration-reopened"]{let q=Qa::legacy();let original=literal(&q.sql());let mut p=child(&q,"migrate",stop,&id());let stdout=p.stdout.take().unwrap();let mut seen=false;for line in std::io::BufReader::new(stdout).lines(){if line.unwrap().contains(&format!("FISCAL_READY:{stop}")){seen=true;break;}}assert!(seen);p.kill().unwrap();p.wait().unwrap();let version=schema::version(&q.sql()).unwrap();assert_eq!(version,if matches!(stop,"migration-after-commit"|"migration-reopened"){2}else{1});q.repo.open_existing().unwrap();assert_eq!(literal(&q.sql()),original);records.push(serde_json::json!({"point":stop,"externallyTerminated":true,"schemaAfterKill":version,"reopenedSchema":2,"legacyReceiptsPreserved":5}));}fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4b/migration-crashes.json"),serde_json::to_vec_pretty(&records).unwrap()).unwrap();}
#[test]fn two_actual_processes_migrate_once(){let q=Qa::legacy();let rows=literal(&q.sql());let a=child(&q,"migrate","",&id());let b=child(&q,"migrate","",&id());let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();assert!(a.status.success()&&b.status.success(),"{:?} {:?}",a.stderr,b.stderr);assert_eq!(schema::version(&q.sql()).unwrap(),2);assert_eq!(literal(&q.sql()),rows);assert_eq!(fs::read_dir(q.root.join("fiscal/recovery/migration-2")).unwrap().count(),1);}
#[test]fn two_actual_processes_selection_cas_has_one_winner(){let q=Qa::legacy();q.repo.open_existing().unwrap();let (_,installations)=q.repo.installation_metadata(10,"").unwrap();let i=&installations.iter().max_by_key(|i|i.revision).unwrap().installation_id;let aa=q.admit(i);let p=q.repo.prepare_activation(ActivationIntent::Select,Some(i),Some(&aa),None).unwrap();fs::write(q.root.join("selection-request.json"),core::canonical::bytes(&p.action).unwrap()).unwrap();let a=child(&q,"select","",&id());let b=child(&q,"select","",&id());let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();assert!(a.status.success()&&b.status.success(),"{:?} {:?}",a.stderr,b.stderr);let text=format!("{}{}",String::from_utf8_lossy(&a.stdout),String::from_utf8_lossy(&b.stdout));assert!(text.contains("STALE_GENERATION"));assert_eq!(q.repo.selection_status().unwrap().selection.generation,1);}
#[test]#[ignore="Native subprocess helper exercised by migration and CAS tests"]fn process_child(){let root=PathBuf::from(std::env::var_os("FISCAL4B_ROOT").unwrap());assert!(root.starts_with(std::env::temp_dir().join("opencode")));assert!(root.file_name().unwrap().to_string_lossy().starts_with("5d3b4b-"));let mut repo=Repository::new(root.clone(),Policy::import_qa());repo.clock=Clock{fixed:Some(Arc::new(Mutex::new("2026-10-28T12:00:00Z".into())))};if std::env::var("FISCAL4B_MODE").unwrap()=="migrate"{let start=std::time::Instant::now();loop{match repo.open_existing(){Ok(_)=>break,Err(e) if e.code=="BUSY"&&start.elapsed()<std::time::Duration::from_secs(30)=>std::thread::sleep(std::time::Duration::from_millis(50)),Err(e)=>panic!("{e:?}")}}}else{let v=core::strict_json::parse(&fs::read(root.join("selection-request.json")).unwrap()).unwrap();let action:Action=core::decode_closed(&v).unwrap();let op=std::env::var("FISCAL4B_OP").unwrap();let start=std::time::Instant::now();loop{match repo.mutate(&op,6,|_|Ok((action.clone(),BTreeMap::new()))){Ok(_)=>{println!("SELECTED");break},Err(e) if e.code=="STALE_GENERATION"=>{println!("STALE_GENERATION");break},Err(e) if e.code=="BUSY"&&start.elapsed()<std::time::Duration::from_secs(30)=>std::thread::sleep(std::time::Duration::from_millis(50)),Err(e)=>panic!("{e:?}")}}}}
